package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	reader := bufio.NewScanner(os.Stdin)
	reader.Split(bufio.ScanLines)

	var lines []string
	for reader.Scan() {
		lines = append(lines, reader.Text())
	}

	if len(lines) == 0 {
		return
	}

	// Initialize input iterator
	type Input struct {
		list  []string
		index int
		max   int
	}
	obj := &Input{list: lines, index: 0, max: len(lines)}

	next := func() string {
		if obj.index < obj.max {
			s := obj.list[obj.index]
			obj.index++
			return s
		}
		panic("ArrayIndexOutOfBoundsException 'There is no more input'")
	}

	nextInt := func() int {
		i, _ := strconv.Atoi(next())
		return i
	}

	myconv := func(i []int, no int) string {
		switch no {
		case 8:
			strs := make([]string, len(i))
			for idx, v := range i {
				strs[idx] = strconv.Itoa(v)
			}
			return strings.Join(strs, " ")
		default:
			return ""
		}
	}

	N := nextInt()
	_ = N

	s := strings.Split(next(), "W")
	var output []int
	for _, part := range s {
		if part != "" {
			output = append(output, len(part))
		}
	}

	fmt.Println(len(output))
	fmt.Println(myconv(output, 8))
}

